/**
 * data/bibleBookFiles.ts
 * ---------------------------------------------------------------------------
 * Static require() map for all 66 KJV books. Metro needs literal string paths
 * for require() to resolve them, so this file is generated rather than built
 * dynamically. Each entry resolves to an asset module (not inlined JS, thanks
 * to the .bjson extension registered in metro.config.js) — the actual verse
 * data is only read from disk when loadBook() is called for that book.
 * ---------------------------------------------------------------------------
 */

